def download_sync_request(sync_id: str, github_token: str) -> Dict:
    import json
    import base64
    import requests

    # Build file path
    file_path = f'sync/requests/{sync_id}.json'

    # GitHub API request
    url = f'https://api.github.com/repos/HVSCMA/hvscma-cmas/contents/{file_path}'
    headers = {
        'Authorization': f'token {github_token}',
        'Accept': 'application/vnd.github.v3+json'
    }

    response = requests.get(url, headers=headers)

    if response.status_code == 200:
        file_data = response.json()
        content = base64.b64decode(file_data['content']).decode()
        sync_request = json.loads(content)

        return {
            'success': True,
            'sync_request': sync_request,
            'file_sha': file_data['sha'],  # Needed for updates/moves
            'file_path': file_path
        }
    else:
        return {
            'success': False,
            'status_code': response.status_code,
            'error': response.text
        }

