def move_sync_file(sync_id: str, from_dir: str, to_dir: str, github_token: str, update_content: Dict = None) -> Dict:
    import json
    import base64
    import requests

    # File paths
    old_path = f'sync/{from_dir}/{sync_id}.json'
    new_path = f'sync/{to_dir}/{sync_id}.json'

    headers = {
        'Authorization': f'token {github_token}',
        'Accept': 'application/vnd.github.v3+json'
    }

    # Get existing file
    get_url = f'https://api.github.com/repos/HVSCMA/hvscma-cmas/contents/{old_path}'
    get_response = requests.get(get_url, headers=headers)

    if get_response.status_code != 200:
        return {'success': False, 'error': 'Source file not found'}

    file_data = get_response.json()

    # Prepare content (use updated content if provided)
    if update_content:
        content = json.dumps(update_content, indent=2)
    else:
        content = base64.b64decode(file_data['content']).decode()

    encoded_content = base64.b64encode(content.encode()).decode()

    # Create new file
    put_url = f'https://api.github.com/repos/HVSCMA/hvscma-cmas/contents/{new_path}'
    put_payload = {
        'message': f'🔄 Move sync {sync_id}: {from_dir} → {to_dir}',
        'content': encoded_content,
        'branch': 'main'
    }

    put_response = requests.put(put_url, headers=headers, json=put_payload)

    if put_response.status_code == 201:
        # Delete old file
        delete_payload = {
            'message': f'🗑️ Remove old sync file: {old_path}',
            'sha': file_data['sha'],
            'branch': 'main'
        }

        delete_response = requests.delete(get_url, headers=headers, json=delete_payload)

        return {
            'success': delete_response.status_code == 200,
            'old_path': old_path,
            'new_path': new_path,
            'created': put_response.status_code == 201,
            'deleted': delete_response.status_code == 200
        }

    return {'success': False, 'error': 'Failed to create new file'}

