def list_sync_files(directory: str, github_token: str) -> Dict:
    import requests

    # GitHub API request
    url = f'https://api.github.com/repos/HVSCMA/hvscma-cmas/contents/sync/{directory}'
    headers = {
        'Authorization': f'token {github_token}',
        'Accept': 'application/vnd.github.v3+json'
    }

    response = requests.get(url, headers=headers)

    if response.status_code == 200:
        files = response.json()
        sync_files = [
            {
                'name': f['name'],
                'sync_id': f['name'].replace('.json', ''),
                'size': f['size'],
                'download_url': f['download_url'],
                'sha': f['sha']
            }
            for f in files if f['name'].endswith('.json')
        ]

        return {
            'success': True,
            'files': sync_files,
            'count': len(sync_files)
        }
    else:
        return {
            'success': False,
            'status_code': response.status_code,
            'error': response.text
        }

