def poll_new_requests(github_token: str, last_check_time: str = None) -> Dict:
    import requests
    from datetime import datetime

    # List files in requests directory
    result = list_sync_files('requests', github_token)

    if not result['success']:
        return result

    new_requests = []

    for file_info in result['files']:
        # Download and validate each request
        sync_id = file_info['sync_id']
        download_result = download_sync_request(sync_id, github_token)

        if download_result['success']:
            sync_request = download_result['sync_request']

            # Check if request is newer than last check
            request_time = sync_request.get('created_at', '')
            if not last_check_time or request_time > last_check_time:
                new_requests.append({
                    'sync_id': sync_id,
                    'sync_request': sync_request,
                    'file_sha': download_result['file_sha']
                })

    return {
        'success': True,
        'new_requests': new_requests,
        'count': len(new_requests)
    }
